INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (6065, '嗯，是时候让你接受训练了。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Yes, I do believe you are ready...
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (6067, '嗯，是时候让你接受训练了。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Yes, I do believe you are ready...
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (6073, '是该让你进行训练了……$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Yes, it is time, $c.
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (9334, '愿这些物品能在往后的战斗里帮上你的忙。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Blessed Wizard Oil
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (9335, '谢谢你，$N。这是你的神圣磨刀石，请谨慎使用。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Consecrated Sharpening Stone
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (9336, '给你，$N。外面小心些。我们人手不多，可经不起战场上再多伤亡。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Major Healing Potion
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (9337, '给你，$N。外面小心些。我们人手不多，可经不起战场上再多伤亡。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Major Mana Potion
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (9343, '收下这面战袍，骄傲地穿着它。也许你的作为会激励更多人拿起武器，支援我们对抗天灾军团的战斗。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Tabard of the Argent Dawn
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (39980, '你为这个世界立下了大功，$n。我们终于可以安宁了。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You have done the world a great service, $n. Finally, we can have peace.
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (39981, '你为这个世界立下了大功，$n。我们终于可以安宁了。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You have done the world a great service, $n. Finally, we can have peace.
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41274, '啊，友情——对艺术的热爱——对更高存在的虔诚——还有那永世奉献与忠诚的誓言。真是些了不起的范例，你做得太好了！老实说，我几乎把它们全都忘了，请原谅我的失礼。这把弓自有主见，有时连它自己射箭我都察觉不到！谁知道呢，说不定你出门的路上就成了它的下一个目标！$B$B<奎·Q一想到这儿就笑了。>$B$B喏，让我为你的辛劳给点奖赏。收下这箱子，里头是艾泽拉斯最精美的衣物。用它们的魅力去讨好你心里珍视的人吧！') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Lavishly Decorated Container
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41279, '<你猜想自己看到的是这位土灵脸上的笑容。巨人身上取下的粗糙宝石在他宽大的手掌里显得很小。他只点了点头，随后让你再次跪下。$B$B当他的手掌再次按上你时，你眼前的一切清晰了许多，尽管这过程依旧让你疲惫不堪。三颗宝石在你内视中显现。所幸你认得它们：一颗火烬石、一颗星红宝石和一颗黄水晶。接着你看到同样的宝石被切出一种你从未见过的刻面。你凝神细看，记住了每一个动作。这份智慧就此刻入你的心中。>') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Plans: Sharpened Citrine Gemstone Plans: Radiant Ember Gemstone Plans: Glowing Rub
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41282, '<这位匠人端详着那枚刻面过的活力宝石。他琥珀色的眼睛仔细审视着这颗闪亮红宝石的每一道切面与棱角。评定完毕后，他把宝石递还给你——随后躬身致意。$B$B你通过了考验！瑟格雷恩把你引到他的工作台前，迫不及待要把自己的知识传授给这位新学生。>') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- The following spell will be cast on you: Gemology
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41283, '嗯，嗯，没我想的那么糟。不过，这明显带着姆埃瓦那种粗糙手艺的印记。好在现在你落到我手里了，用不了多久，我就能把你调教成一个能用的珠宝匠！先做这件可爱的小饰品吧，照着做应该不难……但愿如此。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Plans: Crystal Earring
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41284, '我不知道你怎么想，但看着这些小宝贝在探矿镜的光下闪闪发亮，我是永远看不腻的。你一定能理解。既然说定了——来，听仔细，我可不说第二遍！') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Plans: Dazzling Aquamarine Loop
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41285, '血迹斑斑、湿漉漉、满是泥浆。唉，看到我一件得意之作被如此糟践，真让我心痛。不管怎么说，谢谢你把它取回来。告诉我，你是在他那被打烂的尸体上找到的，还是被别人的脏手顺走的？算了，别告诉我，我宁愿不知道。$B$B作为你这桩高尚之举的回报，我来教你亲手制作这条项圈。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Plans: Alluring Citrine Choker
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41287, '干得漂亮，我在这儿很少能一次拿到这么多珠宝加工材料。我想得向古尔米瑞道声谢，毕竟在等新情报的这段时间，他总算给了我一件实实在在的活儿。$B$B不过说回你。让我教你怎么做出这些精致的小饰品。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Plans: Crystal Earring
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41288, '或许很微弱，但这些宝石里确实透出力量。最好的珠宝匠能从中提炼出强大的精髓，并将其增幅到前所未有的地步。若容我说一句：总有一天，你也会走到那一步。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Plans: Dazzling Aquamarine Loop
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41289, '令人心惊的消息。你描述的这些，我听着太熟悉了——许多巨魔帝国都毁在自己的狂妄上，自以为高踞于族人或神灵之上。看到你安然归来，我就更放心了。$B$B那么，我们是不是该从这些残破的书页里挖出点线索了？') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Plans: Alluring Citrine Choker
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41291, '湿漉漉还在滴水，但完好无损。感激之情自不必说，我的学生。那么，我们继续吧。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Soggy and dripping, but still intact. My gratitude is guaranteed, pupil. Well then, let us proceed.
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41292, '了不起，如此深刻的切割与打磨。谁都看得出你为这些作品倾注了多少血汗与泪水。人赋予作品的生命，与技术步骤同样重要。没有灵魂的首饰只是一件商品，是对这门手艺千年传承的亵渎。$B$B而你已证明，你的心跳与艾泽拉斯同频——你与它的精魂共鸣，并把那份能量注入自己的艺术。作为我的新学生，请允许我把神圣的知识传授给你。这是你应得的。$B$B哦，若你以后遇见我从前哪个学生，告诉他们随时可以来看我——我想，隔了这些年，有个人做伴也无妨。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- The following spell will be cast on you: Artisan Goldsmith
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41293, '<巧匠端详着你的成品与那件仿制品。>$B$B接近了。没有我的指点，你能把我的学生的步骤复现到这种程度，着实惊人。不过，要衡量你真正的潜力，我要你在我的指导下亲手做出一件作品。来，仔细听好，让我看看你听得够不够认真。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Plans: Elaborate Golden Bracelets
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41294, '以本来面目观照世界，看似简单寻常，但唯有愿意深入其中的人，才能真正洞悉其本质。$B$B你已向我证明你是这样的人。用心听我说的话，它们会给你新的领悟。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Plans: Heart of the Sea
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41295, '<看到你带来的物件，巧匠出奇地郑重。他轻声一笑，才重新看向你。>$B$B谢谢你。我很高兴你来找我。来，我把加莉特蕾娅在我门下时设计的一件东西送给你。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Plans: Staff of Gallitrea
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41299, '听来悲惨又骇人——无论是来自我们母星的德莱尼人的干预，还是库米沙一心想要回到故土的执念。我带着族人来到此地，是为了寻找一处避风港，一处终有一天能再度称之为家的庇护所。有了这卷轴上的智慧与德莱尼水晶的魔法，我们或许能实现它——一起。$B$B请放心，你为我族人所做的一切不会被遗忘。既然你读不懂这经卷，就让我为你讲讲其中的奥义吧。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Plans: Draenethyst Baton
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41301, '我看你回来了。现在也让我们确保你能顺利离开……') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- I see you have returned. Now let us ensure you will be able to leave as well...
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41302, '<塔瓦斯德打开袋子，一脸恼火。>$B$B什么？！这才是我被答应的一半！哦，这个该死的刽子手、卑鄙的滑头，连他那帮凶神恶煞的保镖也一起见鬼去吧！不过，至少我还活着，对吧？这得谢谢你——说真的，我很感激！你毫不犹豫地为我冒险，如今这种事可不多见。但愿这帮恶棍不会再来找我麻烦。$B$B不过请告诉我：你替我送去的那件首饰，你莫非是珠宝匠？若是，请允许我把一份专利设计分享给你，作为你这份英勇的酬谢！') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Plans: Delicate Mithril Amulet
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41303, '格里兹比？不，他没离开棘齿城，至少不是坐船走的。但他确实到过这里，这点可以肯定。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Grizzby? No, he didnt leave Ratchet, atleast not by boat. But he did make it here, thats for sure.
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41305, '哦，哇！这东西几乎跟我的鼻子一样大！那些冒险者果然没吹牛。还有你带来的项链，做工精细得惊人，真了不起。我说过吧，你在珠宝加工上有天分。真的，你帮了我大忙。藏宝海湾那些自以为了不起的家伙，看到这宝贝准会流口水，你等着瞧！为答谢你这一路的辛苦与帮助，我把一份我个人最中意的设计分享给你。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Plans: Delicate Mithril Amulet
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41306, '你是来帮可怜的萨赫希的吗？') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Are you here to help poor Sahrhee?
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41309, '嚯，这才是好东西。我一眼就看出，用这神奇的混合物能把特拉希斯那摊烂摊子救回来。你是跟萨拉辛一起来的？他是个独来独往的……男人？还是蛇？我不清楚，不过到目前为止，他倒没拒绝过跟我长谈珠宝加工的历史与艺术。谁知道呢，说不定哪天我会跟你讲讲我俩是怎么认识的！$B$B既然你帮我避免了一场尴尬的顾客冲突，那就让我给你点回报。我猜你珠宝加工也不差，对吧？别惊讶，我毕竟是这行的大师。就让我免费分享些心得，权当报酬。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Plans: Ornate Mithril Bracelets
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41312, '宝石被劈开了？有意思，不过以那座塔的状况倒也不意外。可把它那样藏起来——麦迪文到底在想什么？还有这个聚焦器……足以证明龙族对掌管魔法一事确有其永恒的职责。我不觉得活着的凡人能造出这种增幅能量流动的装置。$B$B说来苦乐参半，你懂吗？我早已宣誓放弃术士的身份，却无法否认：这第二次帮你，让我心中一种久违的感觉重新亮了起来。看着你完成这件事，我对你能让塔中恐怖安息这件事更有信心了。带上这枚修复好的杖头，再去塔里搜寻剩下的部分。毫无疑问，这会在你探索卡拉赞时起到关键作用。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Sceptre Head of Medivh
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41315, '简直出色极了。我们所见印证了我的猜想：魔网水晶是一种能量导管，一旦暴露在高度浓缩的魔法下，便会显现为奥术魔物。你若细看，两块水晶残骸完全相同——这意味着血精灵从蓝龙军团那里取得水晶后，改造了自己的那一块；究竟是用强夺还是合作，我也说不准。$B$B多亏你，我对这片土地及其居民的了解又深了一层。不过，得知蓝龙军团正在做这种可疑的事，仍令人不安。他们很少在意凡人的事务，却会毫不犹豫地阻止对艾泽拉斯魔法的滥用。眼下我们只能观察，并期盼最好的结果。$B$B至于你的奖励：你也是个能干的珠宝匠，对吧？那就让我教你怎么做出一把能增幅持有者魔法能力的法杖。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Plans: Regal Twilight Staff
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41318, '东西都拿到了？太好了，那我们来验证一下这个猜想如何？$B$B<凡兹翻开书页，把它高高举过头顶。当它靠近空白页时，那些核心与精华开始液化，转移到羊皮纸上——最终凝结成文字，补全了这件首饰的制作说明。>$B$B哇！这真是绝了！我之前说的那些关于这本书的话收回，不得不承认，这玩意真带劲。太不可思议了，过来，我们一起把这一页研究透——没有你的投入，我们走不到这一步！') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Plans: Mastercrafted Diamond Crown
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41319, '干得漂亮。光是弄到一颗这样的宝石已算了得，我简直无法想象你为拿到三颗费了多少功夫！好，都交给我吧，我正想创作一件杰作！$B$B<凡兹夺过材料，小手飞快地动起来。几分钟后，她把那枚精巧的镜片举到阳光下，正对着空白页。令人意外的是，聚焦的光束非但没有烧焦纸面，反而在原本空白的纸上浮现出繁复的文字。>$B$B我找到了！大获成功！是时候收获我们的成果了！过来，我们一起读读看！') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Plans: Mastercrafted Diamond Bangles
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41327, '$N，我由衷感谢你为避难所做的一切。卡斯塔尔及时联系上了我。再晚一步，后果不堪设想。那么，说说我想跟你说的事……$B$B<阿克资阿多向你呈上一颗浑圆无瑕、泛着青绿光泽的水晶，是你从未见过的东西。>$B$B你眼前这颗是纯净的德莱尼水晶宝石，是我族在德拉诺时最珍视的稀有之物之一。它的地位近乎传说，当然并非童话里那种。虽然只是推测，但我猜这一颗诞生于塔斯达尔的裂隙魔法与我的相撞之时。我想把它给你，作为答谢——也作为一个承诺。只要你有需要，避难所的德莱尼人都会相助，因为没有你，我们早已不复存在。恩基尔·托拉拉尔，朋友，愿扭曲虚空的风眷顾你。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Pure Draenethyst Gemstone
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41328, '过程很累人，但总算成了：又一颗纯净的宝石。请好好保管它。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Pure Draenethyst Gemstone
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41329, '唉，你就只能弄到这个？') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Aw, was this the best ye could get?
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41330, '这才是好东西！弟兄们都已经在舔嘴唇了。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Thats the good stuff! The lads be already licking they lips.
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41331, '嚯，你这是从哪儿弄来的？这玩意儿够在海盗王的餐桌上敬一杯的！要是真有那么个海盗王的话……') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Oho, now whered you get that? Something yed toast at the table of the Pirate King! If there were one
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41332, '我的天老爷！这鬼东西的滋味像海妖的亲吻。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Shiver me timbers! The damned thing feels like the kiss of a Siren.
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41336, '当年在埃达拉斯，我们奉艾萨拉女王之命，在奥术圣殿里研究过无数如今早已被遗忘的符文。其中许多我已随时间淡忘，还有一些则因羞愧而不愿想起。不过看来，那段旧日学识让我们获得了新的智慧——这份智慧你可以自行斟酌使用。来，仔细听好。该上新课了，学生。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Plans: Golden Runed Ring
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41342, '结束了。听闻你那些英勇事迹，压在我心头的恐惧正在消散。我会用窥视翡翠梦境的能力，把这块碎片送回我祖父身边。光是握着它，我就又能感到他那光辉而强大的气息。$B$B他要完全恢复力量还需要相当长的时间，不过伊瑟拉和他的荒野之神同伴们都在他身旁，守护着这位亲爱的朋友与导师。$B$B你对白鹿及其传承的忠诚值得称道。为褒奖你这无私的英雄之举，就让我把变化为玛洛恩雄鹿形态的诀窍传授给你。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Glyph of the White Stag
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41343, '一支大得滑稽的蜡烛。你这人爱开玩笑是吧？') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- A comically large candle. Are you a jokester?
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41344, '大蜡烛给大胡须！我在这鬼地方的活儿干完了。大胡须把这个送给你，当作谢礼。很好玩的书，你看！') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Tome of Polymorph: Rodent
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41345, '大海轰鸣，一股恐惧的浪潮笼罩艾萨拉。有什么东西正从海中升起！') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- The seas rumble and a wave of dread washes over Azshara. Something emerges from the ocean!
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41346, '箱子打开，一股潮湿的气味涌了出来。里面是一些锈迹斑斑的小玩意——还有一件碎裂之物，竟出奇地完好。你把它拿起来，感到一股危险的气息自其中透出。令人心惊。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Bottom Piece of an Ancient Idol
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41348, '<搜寻看来毫无希望，这本日志想必也不会有什么收获。>') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- <The search seems hopeless, surely this journal will not yield anything either.>
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41351, '<蒂莉亚为你完成的任务震惊得说不出话。她端详着失而复得的珍宝，慢慢镇定下来，开口道。>$B$B太不可思议了，简直令人惊叹！你是个了不起的侦探，这么快就查清了这桩十年前的悬案。若我还在自己的庄园，我会让我的兄弟为你授勋、纳入我们的随从。可惜啊，我想这世界的精彩才是你的召唤，而我这不死的躯体却把我困在此地。不过别担心——项链回到我手里，我便能带着轻蔑忍受这无尽的囚笼。$B$B如约，这份东西归你：一枚珍贵红宝石戒指，出自这座塔的主人、守护者麦迪文之手。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Jeweled Ruby Ring
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41354, '信不信由你，你展现出了极大的善意。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Believe it or not, you have shown great kindness.
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41355, '一件极珍贵的物品。这座昔日雄城最后的遗物之一。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- A most treasured item. One of the final relics of this once mighty city.
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41358, '这顾虑很合理。我本无需向你解释——不过我想阿尔多雷尔不一样。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- A fair concern. I owe you no explanation – but I suppose AlDorel is different.
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41360, '我一直害怕有一天要与自己称作朋友的人为敌。唉。$B$B凯斯利尔和许多上层精灵聚居地一样，曾充盈着魔法——那些魔法已随岁月湮没，而我是这片土地上尚未逃离的最后一位幸存者。自从湖水吞没我的家，这些龙族器物就一直在我手里。挑一件吧，它归你了。留个念想，记得我。后会有期。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Claw of the Mageweaver Rod of Permafrost Shard of Leyflow
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41362, '我很感激你的付出，$N。这绝不是轻松的差事，你却这么快就给我弄来了这么高品质的材料。$B$B像山脉之血这样的宝石，需要极高的精准与耐心。只要多施加一丝不该有的力道，整颗宝石就会裂成两半。仔细看着，我只有一次机会教你。做完之后这颗宝石就归你——就当是谢你给我带来这么一件稀奇的样品。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Gorgeous Mountain Gemstone Plans: Gorgeous Mountain Gemstone
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41363, '有意思。这些样本散发的魔法我并不陌生，乍看之下，我甚至要说它们透着德鲁伊的法术。当然，我不该急着下结论。还需要在塞纳里奥议会做进一步研究——他们那些可敬的德鲁伊想必能弄清它们狂暴生长的根源。$B$B$N，我很感激你。请收下一件，作为你辛苦的补偿。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Mana Potion Greater Healing Potion
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41364, '这么说影牙城堡很快就要被攻打了。很好。既然你来了，不介意帮我个忙吧？') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- So the Shadowfang Keep will soon be raided. Good. While youre here, you wouldnt mind doing me a favo
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41366, '愿他的灵魂能在圣光中重归安宁。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Necklace of Redemption
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41367, '噩梦的黑暗曾笼罩我的思绪，把我一向压住的情绪都逼了出来。某种程度上，我也后悔事情走到这一步。$B$B<纳尔帕克把赞妲拉的头颅放在地上。>$B$B活干得好，就该有好报。谢谢你，$N。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Kolkar Drape
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41368, '这些笔记很珍贵，非常珍贵。我不觉得这时候就能让血色十字军造不出光铸护甲，但至少它回到了我手里。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Solid Sharpening Stone Solid Weightstone
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41369, '太骇人了。即便只是某个狂暴元素残留的遗物，它散发出的压迫感依然令人窒息。有了这份能量源泉，我就能把法杖与束具合而为一，重现麦迪文之杖。不过它虽已复原，却仍不完整——杖头丢失了。至于去哪里找，我就无从知晓了。若它落到你手里，再来找我，我会尽力再帮你一次。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Scepter Rod of Medivh
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41372, '我把麦迪文之杖托付给你——它是魔网魔法的导管，也是异界原初能量的容器。凭它，你可以号令卡拉赞本身狂暴的魔法洪流。别因此自满；你固然强大，但真正能驾驭这法杖的，唯有它从前的主人。尽管如此，这座被诅咒之塔最深处的秘密如今已伏在你脚下，只等着那位意志足够坚定、敢于闯过险途之人前来揭开。$B$B去吧，去取回你如此英勇奋战所追寻的真相！让征服卡拉赞成为你英雄传奇中的一座里程碑！') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: The Scepter of Medivh
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41373, '啊，《科赞食谱》，还是加斯蒂诺亲笔，你在哪找到的？') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Ah, “Recipes of Kezan” by none other than Gastino, whered you find that?
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41374, '一张皱巴巴的纸。不管怎么说，看到它变成这样都让人难过。我替你把它复原——把它拿在手里，让我想起了它原来的样子。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Recipe: Empowering Herbal Salad
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41375, '你在取笑我吗？这看上去像是小孩子写的——$B$B<莱德罗斯默默盯着空中看了片刻。>') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Are you mocking me? This looks like something a child wro–$B$B<Lydros stares silently into thin air 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41376, '好了，符文既已补全，现在就能用了。至于你愿不愿意用，那就随你。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Glyph of the Arcane Treant
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41378, '干得漂亮。现在把血交给我，我来准备所需之物。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Impressive. Now, give the blood to me. I will prepare what is needed.
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41379, '纯净的狼人之血，正如乌尔所描述……是的，这非常有用。不过现在听我说，我有很多事情要告诉你。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Pure worgen blood, just like Ur described... Yes, this will be very useful. But now listen, as I hav
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41380, '这么说，传说中的穆沙镰刀被找到了。大德鲁伊梦风派你来找我，很有见地。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- So, the fabled Scythe of Musha has been found. This Arch Druid Dreamwind has been wise to send you t
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41381, '一如既往的精工之作。现在，把它交给我。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Exquisite work, as always. Now, hand it to me.
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41383, '现在你知道了。我们剩下的时间不多了。你必须找到它们，镰刀才能得到净化。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- So now you know. We dont have much time left. You must find them, so that the Scythe can be cleansed
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41384, '邪恶的普里科利希·怒月死了！确实了得。你救了我们所有人。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- The foul pricolich Gnarlmoon is dead! Impressive indeed. You have saved us all.
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41386, '邪恶的普里科利希·狼人死了！你阻止了他，为瓦琳德报了仇！') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- The vile pricolich Lycan is dead! You stopped him and avenged Velinde!
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41388, '值得称赞。把这几课记在心里，对你今后在这条路上的成就至关重要。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Commendable. Taking these lessons to heart is imperative for your future success on this road youve 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41389, '大师是个难以捉摸的人，我大概永远也弄不懂他的心思。好在我们要的不是这个，对吧？$B$B你带来的这颗珍珠，真是不同寻常。大师的每个学生都会从他——严格说也包括我——那里得到一件私人礼物，作为成就的凭证。我的是我在千针石林杀掉的一只蝎子的尾刺。至于你……你觉得一枚坠饰如何？') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Testimony of Resolve
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41390, '是伦兹克派你来的？很好。我正缺些人手。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Renzik sent you? Good. I could use a bit more manpower.
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41392, '以科赞的矿脉起誓！这味道太呛人了。随便谁闻上一口，壮实的船员也得当场倒地。$N，干得漂亮。虽然我们保住了这一头的作业，但还得查清他们到底从哪儿弄来这些补给——我敢肯定，风险投资公司不过是个中间人。总之，到目前为止你做得很好，我为你备了份奖励。别招惹麻烦，冒险者，我可不想看到你送命。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Operative Cloak Cuffs of Integrity
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41396, '这些就够了。有了这些效力强劲的蘑菇，我能为你调制一剂格外强力的梦境帷幕。没有它，我怕你会过早被拉入梦境，再也回不来。现在打起精神，$N。要获得梦境之视，你得去觐见艾泽拉斯最古老的绿龙之一。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Slumbering Dreamveil
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41397, '我明白了。尽管听着令人沉重，维瑟库斯的轻蔑也可以理解。像他这样的古老存在，在目睹凡人千万年来的种种劣行之后，善意很容易动摇。我仍希望他能继续看到你们这些族人所蕴藏的潜力。$B$B不过，知道他可以沟通、也没有沦为噩梦的牺牲品，总算让我心里一块石头落了地。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Dreamsight Gem
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41398, '<宁静降临暮光林地。梦魇再一次被击退，但能维持多久，无人知晓。你心里明白，翡翠梦境之战尚未结束，然而想到那些坚定的守卫会继续这场正义之战，你便感到一丝慰藉。$B$B在你面前矗立着堪称自然最强之力的存在。青绿色的毛皮如星空般闪耀，他的双眼映出一片深蓝的智慧之海。你以为他力量的重压会把你压垮，可迎面而来的却是那熟悉的暖意——如清晨的阳光微风拂过挂满露珠的青草。$B$B你抬眼上望，视线与这位半神相接，一股力量之感奔涌全身。那是无可比拟的感受：成长、欣赏与爱。来得快，去得也快。仿佛重生一般，你向这位守路者致意，然后让他回到自己的职责中去。>') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- The following spell will be cast on you: Swift Travel Form
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41399, '这枚指环蕴含着巨大的潜力。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Ring of The Dreamwalker Signet of the Dreamwalker Band of the Dr
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41400, '风为你而吹，看来自然眷顾着你。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Stormrage Circlet Stormrage Helmet
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41401, '风为你而吹，看来自然眷顾着你。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Stormrage Mantle Stormrage Shoulderpads
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41402, '风为你而吹，看来自然眷顾着你。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Stormrage Vest Stormrage Raiments
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41403, '风为你而吹，看来自然眷顾着你。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Stormrage Wristbands Stormrage Wristguards
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41404, '风为你而吹，看来自然眷顾着你。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Stormrage Handwraps Stormrage Handguards
