INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41551, '我就知道你不会这么快忘掉我的教诲。不过，温故确实很有必要。像金匠学这般精巧的技艺，若非全心投入便无法精通。我的学生，我很感激你对这门古老手艺的热忱。愿你在其中寻得启发。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- The following spell will be cast on you: Goldsmith
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41552, '<你跪了下来，他石质的手掌轻触你的额头。一股狂喜的力量涌来，你早年从他教诲中学到的一切基础知识，尽数涌回心头。>') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- The following spell will be cast on you: Gemology
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41578, '看吧，你的奖励在此：这顶头盔已重新锻造，随时为你上阵效力。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Helm of the Talon Circlet of the Talon Helmet of the Talon
