INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41631, '看吧，你的奖励在此：这枚护符，如今比以往更加强大。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Lionheart Amulet Lionheart Pendant Lionheart Choker
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41632, '你终于完整了。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Ring of the Cryptstalker
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41633, '看来你终究还算是个像样的$C。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Bonescythe Ring
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41634, '真是妙极了。干得漂亮。斯隆达该好好听着，以你为榜样。她天赋极高，可缺乏纪律这一点，既是我心头的大刺，也是她的。不过，我也只能怪她一半——毕竟我曾向她父母立誓，既要培育她的魔法天赋，也要助她成长为人。$B$B好旅人，我由衷感谢你。走之前，收下一件作为补偿。眼下时局多艰，务必步步留心。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Magilous Tarot Compendium Academy Dropout Slippers
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41635, '办妥了？这就是他们那个杂种首领的首级？他们死得好，那帮家伙既已选了自己的路——一条通向灭亡的路。冒险者，我欣赏你的胆量。来，收下这份奖赏。有你这样的作为，我们或许很快就能重归安稳的日子。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Lumberjack Vest
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41637, '太好了，每次看到他们欢喜的神情，我自己也会笑出来。这些孩子是联盟的未来，而我们责任所在，就是尽力让他们为自己的人生抉择做好准备。我会确保教会知晓你今日的贡献——善行不会被忽视。你自己可有学到什么吗？巴罗岛在王国里是个争议不断的话题，许多迷信的人至今不敢提起它的名字。但无论如何，它都是我们过去的一部分，理应被记住。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Scolding Rod
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41640, '就是它！我真不知道该怎么谢你！要是把这些弄丢了，我怕自己根本承受不住。这里头全是我当巡山人时结识的好友留下的念想——每当公务把他们累垮，他们就会来山里看我、歇歇脚。为了他们，我们得尽快把这里夺回来。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Mountaineers Breaches Cinderfist Treads Snow Wanderers Staff
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41646, '<特工霍桑听完你的发现，长长地叹了口气。他显然疲惫不堪，开始揉眼睛，像是认了输。>$B$B这一整桩事到头来比我希望的还要难解。三名嫌犯的行为都与本案无关，我们又回到了原点。尽管沮丧，我还是得重新开始调查。我会撤销你的副手委任；你为我做的已经省下我宝贵的时间，我不能再多要求你什么。若我运气够好，军情七处会派人来支援我。在那之前，我必须专心办案了。再会，$N。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Blackrock Cleaver Ashwood Bow
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41656, '你是来领赏金的吧？$B$B<阿格娜什指挥官爽朗地大笑。>$B$B你今日的作为或许让裂刃的许多人保住了性命，为此我得谢你。你的行动无愧于部落，更无愧于这份奖赏。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Shatterblade Gauntlets Expedition Boots
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41658, '<阿格娜什指挥官带着几分难以置信看着你。>$B$B你成功了？$B$B<阿格娜什指挥官爽朗地大笑起来。>$B$B你战胜了敌人，击败了科尔拉格！像他这样的强敌本是无畏的难题，可你偏偏站在这里，凯旋而归。今日你该为自己的荣耀而骄傲，因为你做到了极少有人能做到的事。$B$B收下这个，这是部落本身的谢意！') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Doomsong Cuffs Sash of Zarmgeth Leggings of Gethkar
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41660, '荣耀与光荣归于你的名字！你击败了我们的敌人，为部落带来了胜利。我备了几件东西，挑一件，让它陪你走完接下来的路。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Dark Iron Bludgeon Drape of Groldan
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41661, '我希望那位可怜的商人只是被抢了财物，而不是被打得流血——或者更糟。总之，你尽到了自己的本分，对此我不胜感激。我拿不出什么，就收下这幅画吧。那是我画的最后一幅。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Duel of Leaves
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41665, '谢尔伍德公爵是我的挚友，他多次拒绝使用仆人。想到他会在你身上破例，我就觉得欣慰。我的武备库很简陋，眼下又是艰难时世——为你的辛劳，我最多只能以此相赠。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Leafsguard Amberwood Great-Axe
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41666, '啊，你来了！谢谢，谢谢你。要不是你及时赶到，他们怕是要把我的摊子给拆了。按约定——一包免费的琥珀釉甜甜圈，外加一枚小费。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Amberglaze Donut
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41667, '喂，$N，她还在盯着我看吗？唉，那女人让我浑身不自在。对了，马蹄铁拿到了吗？哦，感谢圣光。喏，拿着这个，动作快点。还有——以防万一，比赛期间别露面。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Rod of Stromgarde
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41668, '都交给我吧，一切就绪。你帮了我，可以自己拿一个苹果。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Shiny Red Apple
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41669, '是奶奶派你来的？她还说了那些话？哦，我真想她。她寄来的东西我迫不及待要一一尝遍。听说北风的甜甜圈很有名气。而母亲给我的这个玩具，我会永远珍藏。谢谢你，冒险者。你帮了我一个大忙；作为暴风城的王子，我本该从军械库里挑样东西赏你——可我做不到。那就把我从大主教那里得来的这本书送给你吧。$B$B有空常来跟我讲讲你的冒险，这座宫殿又沉闷又无聊。我需要一个朋友。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Almanac of Prayer
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41671, '随着它被送回，希望也回来了。今年的福音仪式上，我们要与那些信仰已经黯淡的人重新连结——在这片土地被混乱笼罩之时，他们正需要这个。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Robes of the Wailing Nun
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41674, '你杀了这么多？很好！它们的血会滋养土壤，长出的葡萄会带着胜利的甘甜。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Hood of the Pyremaster Crawford Hauberk
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41676, '没了首领，残存的兽人该滚回他们肮脏的故土了。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Ozuks Piercer Blade of the Overlord Steeltooth
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41677, '我在这儿都听见它们炸开了。干得好，挑一件吧。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Amberwood Bracers Dark Iron Gloves
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41678, '很好，这是你的奖赏。若你偏离圣光之道，愿圣光惩罚你。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Amber Shawl
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41681, '肉肉的带回了臭兽人。$B$B卫葛斯要把它搬回去给主人。$B$B臭臭把它弄丢了，就归肉肉的了。$B$B再见，肉肉的。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Hood of the Pyremaster
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41682, '那个袋子你留着吧，我已经用不着了。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Dark Iron Gloves Mageweave Bag
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41683, '干得漂亮，这份奖励你当之无愧。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Blade of the Overlord Ozuks Piercer Steeltooth
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41685, '所以霍桑把你雇为助手，帮他在北风查案。让我看看你查出了什么。$B$B<肖仔细翻过霍桑的日志，又把你在兽人营地找到的那封信读了更仔细的一遍。他神情严峻，把羊皮纸卷起，让你看末尾的印记。>$B$B这是风暴掠袭者氏族的印记。那是个古老的兽人氏族，我们本以为他们在二次大战末期就灭绝了。这封信我读完了，内容与王国的病症吻合：他们下令绑架疏于防范的平民，却不知为何把注意力转向了北风。不过，这还不是整桩事里最令人警觉的发现。先给你应得的奖励吧。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: SI:7 Honorary Medal Loop of the Assassin Operative Cape
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41687, '太好了，这是他们闯进我的地盘、洗劫比尔克庇护所、搅乱我采石计划的报应！他们活该！我得谢谢你。来，挑一件合意的——以你的本事，远远配得上。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Shiv of Nobility Belt of Compassion
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41691, '<老太婆用药杵把草药捣碎，再拌入黏稠的琥珀树液。她搅匀药膏，涂到一条新绷带上。小心地取下旧绷带，又一批药膏敷在小鸭子的伤口上，疼得它好不委屈。女巫动作利落又轻柔地把绷带缠上它的左翼，固定妥当。>$B$B好了，宝贝；这能让它好得很快。像我们这位朋友这样毫无自保之力的小家伙，很少有幸遇到你这样的好心人。看它的样子，它同样记着你的付出。你的行为今日结下了一份了不起的羁绊。务必好好珍视——力量深深根植于这样的联系之中。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Billy
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41694, '可惜了，我们今天失去的都是得力的密探。我会给他们的家人送信，他们为王国所做的贡献不会被遗忘。现在，说说这卷轴……') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Half-dissolved Wedding Ring Pantaloons of Torture
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41697, '任务完成。干得好，$C。遗憾的是，只要那些术士还在活动，我们恐怕终究没法彻底切断这里的恶魔势力。但能拿到多少小胜，我们就拿多少。记住，这是一场拼数量的战争，得把手上的东西用到极致！说到优势——你带回来的这块石碑里，肯定藏着恶魔插手此事的关键情报。我就知道！我会把它带给诺普西，他知道该怎么办。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Harelyss Whip
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41698, '哦嚯嚯，好手艺啊，朋友。等我们按下这个起爆器，让那些爆炸的好东西在他们四周乱飞，那帮抱着恶魔大腿的兽人就有得瞧了！$B$B<鲁夫斯眼里满是狂喜，简直乐得像个胡子拉碴的孩子。>$B$B嚯，这让我想起有一回我差点把暴风城的矮人区给炸了。等我们为这该诅咒的岛屿操心完，我一边喝酒一边讲给你听。矮人一言为定！') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Ez-Thro Dynamite
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41700, '我的罗盘！这么说维里克斯得到了他该得的下场？要我说，他死得好。我们地精有句话：一个地精的不幸，就是另一个地精的财运。罗盘回到我手里，剩下的就是把鸥翼号修到能用。谢谢你的帮忙，$C。维里克斯搜刮来的金币你可以留一些。要是你还想搭把手，我们绝不推辞。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Goblin Nose Ring Verix Navigator Cloak
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41702, '我得承认，我很佩服。我和其他人一直在赌你会带着几条肢体回来，还是我们得从海里把你的软身子捞上来。看来等我们回藏宝海湾，我得输给瑞克基几个金币了。不管怎么说，你的身手真是惊人。少了一个拖累，阿恩伊会松一口气。要是哪天你在外头冒险闯腻了，安德麦的热砂总部永远缺能打的狠角色。考虑一下，你准能融入进去！') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Pennys Crabcracker Tidecaller Chestpiece
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41703, '真让我吃惊，整整一箱值钱的材料。光凭这些，就够重建鸥翼号的外框了。不得不说，我没想到你能办得这么漂亮。不过，愿意跑到这种穷乡僻壤小岛上来的人，本来就够疯的，是吧？总之，我们欠你一个大人情，朋友。地精一言为定！') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Plundered Pirate Hat Tarred Shoulderpads
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41708, '一股异常刺鼻的气味。要从它们身上提炼出可用的毒药得花些时间，但回报会十倍于所费。我得谢谢你——你的协助让这次任务的成功来得比你想的更快。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Lightfooted Mokassins Grips of Mending
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41711, '你说纳迦？！这真是坏消息。若这些蜿蜒爬行的恶徒是这现象背后的黑手，那他们的真正意图我简直不敢去想。眼下我们挫败了他们的图谋。不过我在想：这颗珍珠是一直都在这里吗？若是，它一直就是破碎的吗？若不是，它为何被带到这里，又是谁带来的？纳迦还是鱼人？仍有太多疑问摆在我们面前，而且似乎没有一个容易解答。无论如何，我必须感谢你的协助。今日的发现让我对巴罗无尽的风暴有了更深的理解。等我一回到达文堡，就会把珍珠以及纳迦牵涉其中的事，呈报给博拉勒斯的潮汐议会。以他们近来对库尔提拉斯的不断侵袭来看，恐怕这不会是最后一次。$B$B请收下这个，作为你所作所为的一点微薄补偿。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Hydromancer Cowl Choker of Insight You will receive: Pearlescent
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41712, '<格里塞尔达小心翼翼地读着那封积尘的信，生怕一个不留神就扯破纸页。一丝苦涩而温柔的神情掠过她的脸，她眼中微露惊讶，却不是得知坏消息的那种。取而代之，一抹笑意爬上了她的嘴角。>') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Aquadynamic Fish Attractor
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41715, '$N，你还要再进通灵学院？为使用预言水晶球，你已经付出了不小的代价——或许你愿意再带一个上路。有了它，你便能再次面对大骨库里的凶险。$B$B尽管拿去。这你受之无愧。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Divination Scryer
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41721, '胜利之日终于到来，你的行动为部落占据这片土地铺平了道路。你的作为里处处可见萨尔的智慧。$B$B今日的功劳，自当有赏。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Reachhide Harness Scarweave Leggings Shatterblade Pauldrons
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41724, '我很满意。一想到有人为了力量背弃誓言、朋友与忠诚，我就从心底作呕。你为部落铲除了这样一个卑劣的叛徒。$B$B拿着这个，愿它助你的事业更进一步。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Renegade Battle Boots Mirefang Staff
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41726, '好精良的工艺，一看就知道这工程出自地精或侏儒之手。$B$B有了这些零件，我就能让裂刃哨所的进展再快一步。$B$B我得夸夸你。没有你找回来的这些构件与零件，这座营地还停留在石器时代呢。$B$B挑一件东西吧，但愿它们能派上用场。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Harlekks Battle Wrench Siege Engineer Goggles
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41731, '乌索克宝石的力量正流淌在我的血脉里……这般力量令人狂喜！$B$B我重生了，这都多亏你替我做了所有的事。$B$B<先知莫萨发出一阵低沉而阴森的笑。>$B$B乌索克之坠饰的力量已被抽干，不过我相信你还是能派上点用场。$B$B<先知莫萨露出一个意味深长的笑容。>$B$B再会了，$C。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: The Pendant of Uthokk
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41733, '你不在的时候我做了些研究，也把这机械装置看了一遍。我想至少弄清了该怎么给它供能，但以它现在这副朽坏的样子，我没法保证一定能成。$B$B<塔尔韦格接过材料，开始为装置内的远古能量模块充能。随着一声轻响，机器缓缓转动起来——虽然慢得可怜，还带着老旧的滞涩。>$B$B啊哈！我成功了，多亏你把这件遗物带来给我研究、动手。愿它的力量助你一路顺遂。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Energized Relic Mechanism
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41742, '我能感觉到——火焰中的腐化已经熄灭了。$B$B你在此地的付出意义重大，若没有你，我几乎束手无策。假以时日，这片土地会自我修复，元素也会归于安宁。我会留下来研究这场转变。$B$B为答谢你的作为，我送上一份配得上你辛劳的奖励。带着荣耀去吧，朋友。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Farseers Loop Scarforged Hauberk Hood of Foresight Scepter of Yo
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41745, '看吧，一股伟大的力量已赐予我们。我从没想过能亲眼见到女神本身的力量回应我的召唤。艾露恩之镰已然复原，它的力量而今交由你保管，用以抵御侵蚀我们世界的邪恶。$B$B$C，如此强大的力量也意味着沉重的责任。守护这件神器、向那些威胁我们使命之人施行艾露恩的意志，都托付给你了。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: The Scythe of Elune
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41746, '你把残留物取回来了，干得好。老实说，派一个路过的旅人来替我们收拾烂摊子，我本有些不放心，但看来结果还不错。$B$B请代表我们这些人，收下这些药水，也许你路上用得上。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Minor Mana Potion
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41747, '送卷轴来的？一定是扎尔迪玛派你来的。老实说，我很想念他在塔里的日子——他一直是个出色的学生。$B$B这些卷轴会派上大用场，我向你保证。请收下这个，就当是阿祖拉之塔的一点谢意。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Scroll of Stamina Scroll of Spirit
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41748, '今天失去了一位聪慧的心灵。也许在另一个世界，他真能成为艾泽拉斯的伟大法师之一。$B$B<塞欧克瑞图斯长长地叹了口气。>$B$B我想我再也找不到像他那样的人了，但我仍要谢谢你做了必须做的事。收下这个吧，这是我个人给你的谢意。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Ring of Theocritus
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41749, '这才像话！有了这宝贝，卖给那些暗炉……哦，你还在啊。对！你的奖赏。喏，拿着这个，再添几个金币——你可真让本地精今天走了大运！') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Mosshide Cinch Fenwater Gloves Mosschain Bracers
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41750, '<你还来不及反应，就把孤峰的头颅递给了格里姆比泰。带着不加掩饰的暴怒与憎恨，这豺狼人一把夺过头颅，狠狠咬了下去，将它撕咬得面目全非。做完这一切，他把残余扔进近旁的泥沼，任其沉入沼底。一声嗥叫从格里姆比泰的喉间迸出，其余豺狼人也随之应和。嚎叫声持续了片刻，回荡在整片湿地上空。>$B$B孤峰死了！藓皮真正自由了！你，藓皮的成员，永远！拿着这个，为了杀死叛徒。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Mosshide Ring
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41751, '成了。生死是需要维系的循环，被污染的生命也该有重新绽放的机会。我心中的痛楚仍会持续，但至少我可以确信，赛瑞斯塔兹不再受苦了。平安地去吧，凡人，愿你的旅途不再有悲剧。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Runebound Dagger Flameweave Sash Cuffs of Burning Rage
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41753, '你是个忠诚听话的仆从，$C。为你的效命，我备了一份奖赏。拿着它上路吧——黑暗女王不喜欢有人在她的地盘上无故逗留。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Ancient Flame Pendant
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41755, '一块记载红印家族过往的石碑？！难以置信；快，让我看看！$B$B<托温调好镜片，目光扫过石碑的石面。随着他一行行辨认、读下去，他的脸越来越红、汗也越来越多，到最后手都明显抖了起来。>$B$B你——你……！这东西你从哪儿找来的？！你绝不许提，绝不许！这块该诅咒的石碑，谁都不能知道！绝对不行！来，拿着这个，你的嘴就给我闭紧，听明白了吗？！滚吧！') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Gravelweave Pantaloons Defender of Dorgal Gemlaced Sash
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41757, '死得好。卡兹莫丹残存的龙喉势力被我们狠狠打了一记。接下来就剩收拾残局，把还在我们地盘上乱窜的害虫清除干净。我向你致敬，$N。在我眼里，你就是真正的英雄。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Menethil Greaves Stoutheart Shawl Torwylls Cuffs
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41758, '我在这生物的心脏深处感觉到了什么……它在渴望解脱，去对抗潜伏的黑暗。$B$B<凯姆·蛮鬃一脸困惑，轻轻叹了口气。>$B$B也许我最初的判断错了。唤醒这自然之物、令它陷入疯狂的，并非野猪人那种原始的黑暗魔法。不，是更黑暗、更阴邪的东西……我还有太多疑问需要进一步研究。无论我如何思量，你做得都很好。请收下这个，作为我的一点谢意。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Wildbranch Leggings Fenweave Gloves
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41759, '如此诡异的魔法，那股盘踞在这些生物身上的气息我从未见过。$B$B这等能量绝非自然之物。我必须进一步研究才能查明真相。你干得好，$N。请收下这些金币，愿它们对你有用。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Wildbranch Leggings Fenweave Gloves
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41760, '弗雷德里克，老朋友。你的魂魄残影还留在这件暗淡的小玩意里，早已不复昔日的荣光。总有一天，当我终于离世、离开这方天地时，我会再见到你……$B$B$N，愿祝福与你同在。这枚戒指会被我送去远离黑暗魔掌的湮灭之地，我保证。为你的英勇之举，请收下这件我仅存的贴身之物。你当之无愧。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Grahan Family Seal
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41761, '我没看错人。作为外来的助力，你已证明自己是队里不可多得的人才。若哪天冒险的刺激在你心里淡了，军情七处永远欢迎你这样的人。$B$B请把调查结果报上来。时间不多了。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Clasps of Subterfuge Seabreeze Mantle
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41768, '琥珀木领主如今连送王室文书都雇起低贱的农夫了？倒也不出所料，不过现在这些都无关紧要了。$B$B无论如何，你的差事办得还算妥当。不过我的谢意也是有限度的——我还有关键的情报要分析，所以请你行个方便，让我安安静静处理王国的疾患。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Inheritance Blade Mace of Devotion
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41774, '<团结之基开始咔哒作响，齿轮转动起来。一阵异样的魔力嗡鸣传来，石面泛起蓝光。基座下方缓缓伸出一个托盘，上面放着一枚孤零零的钥匙。>') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Lower Reserve Key
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41776, '<博学者亚沃一手握水晶，一手捧魔典。他念出书页上的咒语，枢纽水晶开始动起来，被涌起的奥术能量激得震颤。震动越来越剧烈，在炫目的紫色火花中骤然破碎，留下两枚金色碎片在他手中。>$B$B成功了！太精彩了，真的！我很惊讶阿苏恩的法术竟近乎完美。稍加练习与改良，我们就能轻松、更安全地快速分解枢纽水晶了。$B$B$N，谢谢你的配合。这些碎片你留着，算作你协助的奖赏。请继续把你能找到的枢纽水晶带给我，好让我接着做实验。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Large Brilliant Shard
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41777, '<亚沃念咒之时，魔法碎片迸出噼啪作响的能量。热量自他掌中升腾，碎片化作液态彼此融合，微微悬在空中。片刻之后，一阵法力迸发——亚沃手中多了一枚枢纽水晶。>$B$B太棒了。亲眼看着它在我面前成形，这一幕我会永远记得。想想看，我们今日的成果竟有赖于一万年前的知识——我族珍视千年的智慧，正是我们韧性的明证。别发愁，年轻的$C，没有你的帮助，这一切都不可能。请留下这枚水晶作为奖赏。我坚信这工艺还能进一步改良，所以若你愿意再采集一次所需材料，我会很高兴。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Nexus Crystal
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41783, '<把书搁到诺普西的桌上，这个侏儒惊叹于这些比例夸张的巨册。>$B$B如此精美，如此古老！要通读这些文献得花些时间。谢谢你，$N。你今天为王国做了一件大好事——保全了他们历史的一部分，哪怕它丑陋又令人沮丧。这些故事能教给我们宝贵的教训，所以对它们视而不见，长远来看只会害了你。记住，知识是你活下去的关键。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Archivists Belt
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41787, '这地方究竟发生了怎样的惨剧……？我一生从未见过如此恐怖之事，光是想到这等亵渎之物存在，就让我脊背发凉。$B$B$N，你敢深入这疯狂漩涡，是如今难得一见的英雄之举。你今日为王国、为整个联盟所做的贡献，在场者会铭记，受惠者会珍视。这些奖励配不上你功绩的分量，但还请你收下。$B$B你可以退下了。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Rufus Trusty Tankard Kinrials Scalpel Noppsys Compendium Nippsys
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41790, '那么……办完了。必要的差事，完成得也算妥当。$B$B<他顿了顿，目光飘向被污染的月亮井，声音因不安而低沉。>$B$B然而……一道阴影仍盘踞在我心头。$B$B倘若乌索尔本人也堕落了呢？倘若这沉默并非出于轻蔑，而是疯狂……腐化？$B$B<他的语气转冷，透出一丝低抑的惊惶。>$B$B这是个危险的念头，我不敢轻率地放在心上。大德鲁伊必须知道此事。$B$B多谢你的……协助。愿风把你带离这被诅咒的地方。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Ursan Trousers Mournshade Sandals
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41805, '嗯……凡人，你做了必须做的事。$B$B他们的心智终于静下来。再没有斯卡丁的低语，再没有扭曲魔法的锁链。只剩下寂静……和被剥夺已久的沉眠。$B$B不必为他们哀悼。他们的火焰如今点燃了我们的意志——他们最后的行为，会比他们曾有的疯狂燃烧得更亮。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Superior Healing Potion
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41809, '终于……那股污秽散去了。$B$B<随着黑暗魔法沉重的压迫消退，他的双翼微微舒展，空气本身仿佛都松了一口气。沼泽浑浊的水面泛起涟漪，像是从漫长的噩梦中醒来。>$B$B格里姆谷会痊愈的。大地记得如何愈合……只要给它时间。$B$B可这场胜利只是从野火上摘下一粒火星。斯卡丁并非独自行动——他们是逃离沉船的鼠辈。格瑞姆巴托吐出了更多同类，像腐斑一样散布在卡兹莫丹。$B$B而最糟的是……他们逃窜得井然有序。这不只是一次流放。他们在侍奉什么。某种古老的东西。某种饥渴的东西。$B$B记住我的话，凡人——这事没有结束。无论他们谋划什么……我们都必须在它找到我们之前先找到它。$B$B而下一次……我们带来的火，恐怕不够。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Hollowed Handguards Robe of the Skardyn Darkcaster Tor Nagaz
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41810, '成了。这枚翠绿符文与符文石一同系于世界之树的精魂之上。凝神体会它的力量吧，你的灵魂将在此地——诺达希尔脚下——重获新生。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Verdant Rune
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41812, '如此美丽——如此宏伟。我多希望能亲眼见到那棵古树，不过还是谢谢你费心将它寻回。我欠你一份人情。请代表我们德鲁伊，收下这份谢礼。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Starbloom Ring
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41813, '麦格尼的胡子啊，整整一箱！还好这玩意儿不容易变质。来，你也拿点尝尝。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Balor Moonshine
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41814, '虽然保存得不好，它终究还是公爵的冠冕。这下能让探险者大厅那帮无赖闭嘴了！谢谢你，$R。这是我答应你的东西。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Drinking Halfhorn Enchanted Glass Kopis
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41818, '我为你成为一名猎人而骄傲。挑一件我的东西带走吧，就当是你成功的纪念。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Wolfbrother Memory of Fenris Ashkin
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41820, '奥金走对了路——派你来而不是自己来，做得不错。一个酋长必须懂得做出恰当的选择。这是很有价值的情报，你辛苦了，该有奖励。也许有一天，我会请你协助处理这件事。我要回去履职，很快就会与大酋长商议。当心阴影，$N，尤其是它们肆意起舞的地方。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Vial of Darkspear Mojo
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41822, '对他们这种渣滓来说，这已是天大的仁慈。拿着吧，它们会带着安舍的光辉，陪你走过阴沉的荒野。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Sunkissed Shoulderpads
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41825, '乌达佩把你派到我这儿来是对的。虽说我们不太愿意与部落打交道，但你的辛劳我记下了，报酬会照付。$B$B看在你话少又懂分寸的份上，我再加一份红包——乌达佩把你教得很好。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Left Right Totem of Anshe
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41828, '骄傲地站直了，部落的子民。唯有血中奔涌着力量与雷霆之人，才能赢得光荣的胜利。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Repurposed Si:7 Dagger
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41834, '尽管我们未必是最后一次见到暗影议会的余烬，但这一场胜利意义非凡。我们对巴罗那片土地并无所求，它却给了我最好的礼物。$B$B基尔罗格起初满怀怨怼，嫉妒格罗玛什被当作英雄庆贺——而他自己却似被遗忘。可他嫉妒错了。我的兄长只是打下了地基。真正将建立未来的，是你、是我，也是基尔罗格。我很高兴他如今也这样看了。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Korkron Crown Voodoo Jerkin Totemic Headdress
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41837, '两块碎片合在一起，就能当作进入城堡废墟的钥匙。当心，你要面对的是燃烧军团的爪牙，还有那些早已被遗忘的邪教信徒。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Key to Stormwrought Castle
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41842, '哦，比我铁炉堡的奶奶还灰头土脸。时间没善待这本古籍，潮湿的空气更是雪上加霜。我会把它妥善封进箱子，然后带回军情七处总部做分析。$N，我由衷感谢你。请挑一件与你的付出相称的奖赏。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Antiquated Slasher Chainmail of Many Pockets
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41844, '哇，收获不小。也许不是我们该送的那批货，但我想海盗湾里那帮贪心的家伙不会太计较。太感谢你了，$N。我们欠你一个大人情。这件东西你拿去，它一直给我带来好运——我还能站在这儿就是证明。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Trusty Goblin Shiv
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41849, '你找到了……以太阳之井起誓，我几乎不敢相信。$B$B<游侠菲亚琳娜举起水晶，斜对着光。阳光在它无瑕的切面上跳跃，折射出层层虹彩。>$B$B这……这绝不是普通宝石。这是一件杰作——是久已失传的手艺的明证。$B$B$C，我们由衷感谢你。我们这就行动——我和游侠们会赶赴现场，尽可能多地回收这种水晶……然后再向瑟伦领主复命。$B$B朋友，你今日为奎尔多雷立下了大功。愿星光永远指引你的道路。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Farstrider Chestpiece Farstrider Leggings
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41853, '<格罗尔丹盯着你带来的人头，朝地上啐了一口。>$B$B哈！这会给暗炉那些鼠辈一个再清楚不过的信号！消息传到他们那位所谓的领袖耳朵里只是时间问题。就当是个教训——惹铁炉堡的矮人之前，最好先掂量掂量，否则就得付出血的代价！') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Shoulderpads of Dun Kithas Grim Mantle
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41856, '干得漂亮，$R！我这就让矿工们进场。用不了几天，我们就能重新开采，丹基塔斯也能再度恢复往日的荣光。$B$B请收下这个。它在我家传了好几代，但现在……是时候让它再次尝尝血的味道了。这是你应得的。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Helmet of Dun Kithas Grim Girdle
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41858, '屠夫的死讯传来，老实说，我很痛快。希望这是最后一次见到那些鱼人。现在我总算能专心于真正要紧的事——与龙喉的战争。我们还有更大的鱼要收拾。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Hollowgrip Gloves Legguards of Dun Kithas
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41864, '你让我们感到骄傲，小子。$B$B再次看到这面战旗……是啊，让人热血沸腾。兽人践踏了我们的城墙，却夺不走我们的精神。$B$B它重新飘扬在丹基塔斯上空，我们的人民就会记起自己是谁——以及我们为何而战。$B$B干得好。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Shield of Baggoth
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41868, '<多尔萨斯眯眼看着样本，在手中来回翻动。他的表情阴沉下来。>$B$B正如我所担心的……这不是什么随机产生的腐化。这是暗影诅咒——正是当年莫德古德在格瑞姆巴托释放的那种灾厄。$B$B而且它至今仍在活动。这么多年过去，诅咒依然在渗出、蔓延，越过废墟。石头挡不住它，时间也没能削弱它。若无人出手……整片区域都会沦陷。这已远超我们独自应付的范畴。我会传信给达拉然的法师们，他们必须知道发生了什么。至于我们……眼下只能守望，并祈祷。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Greater Healing Potion
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41870, '<哈尔菲格仔细听你讲述战斗经过。他饱经风霜的脸第一次松缓下来，嘴角浮起一丝疲惫的笑。>$B$B是啊……这正是我一直想听到的消息。你把他们打得够狠，是吧？我胸口都感觉到了——像是有副重担挪开了，哪怕只挪开一点。$B$B我再也没法抱住我的儿子……再也听不到他的笑声在厅堂里回荡……$B$B但多亏了你，别的父母也许还能。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Trashtalon
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41879, '水晶！$B$B<格鲁克森在手中翻看着它，显然十分满意。>$B$B和我设想的一模一样——完美无缺。这把锤子会因此变得非同凡响。$B$B那我得赶紧动手了。也许这一次……父亲终于会看到我的本事。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Slatebeard Amulet
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41882, '<地方法官胡尔达姆仔细听着，显然大为赞叹。>$B$B以熔炉与磐石起誓，你做到的远比我敢期望的更多！丹基塔斯与格里姆高地的居民欠你一份大人情。请收下这份奖励，作为我们的谢意。$B$B但也别就此松懈——山里还有龙喉的渣滓在游荡。我们矮人最清楚，山中的太平是万万轻信不得的。保持警觉，斧头别离手。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Chestguard of Dun Kithas Magistrates Brim Hat Stolgaz Shoulderpa
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41884, '<地方法官胡尔达姆带着几分难以置信看着你。>$B$B你成功了？以我的胡子起誓，我简直不敢相信！$B$B多亏你的辛劳，许多漫长而艰苦的战斗得以避免。丹基塔斯的矮人会永远记着你的恩情！请从这些东西里挑一件，就当是我们所有人的谢礼。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Doomsong Cuffs Sash of Zarmgeth Leggings of Gethkar
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41887, '我必须提醒你，这配方要用得谨慎。材料一旦用错，做出来的东西会与翡翠猫鼬药剂截然相反。$B$B建议你严格照着配方来。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Recipe: Concoction of the Emerald Mongoose
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41888, '你回来了——还带回了英雄勋章。你在那些险恶之地所做的努力并非无人知晓。每一场胜利，都让我们的立足之地更加稳固。$B$B联盟为你的英勇致谢。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: War Supplies Cache
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41889, '这些圣物已说明一切。伊恩辛迪斯不复存在，巫师领主的手也再难抬起。$B$B火焰之王会感受到这一击，并明白联盟随时准备再次熄灭他的烈焰——只要需要。收下这批补给，保持戒备。深处也许还潜伏着更多。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Molten Supplies Cache
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41890, '这些徽章会传出清晰响亮的讯息：你再次证明了自己的力量。我们要借着这股势头继续推进。$B$B收下你的奖励，勇士。保持警觉，战争不会停歇——我们也不会。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: War Supplies Cache
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41891, '你带着胜利的徽章回来了。很好。这些足以让敌人明白：他们的黑暗挡不住我们的力量。你每挥出一击，都为部落开辟前路。$B$B你的忠诚不会被遗忘。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: War Supplies Cache
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41892, '这些圣物已说明一切。伊恩辛迪斯不复存在，巫师领主的手也再难抬起。$B$B火焰之王会感受到这一击，并明白部落随时准备再次熄灭他的烈焰——只要需要。收下这批补给，保持戒备。深处也许还潜伏着更多。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Molten Supplies Cache
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41896, '好浓烈的邪门法术！这正是我要找的东西。你干得好，也跑得够远。我送你一份阴影的庇护，善加使用，一路平安。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Restorative Potion Scroll of Protection III
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41897, '干得漂亮。这些徽章证明你击穿了他们的防线，粉碎了他们的意志。我们要借这股势头深入他们的据点。$B$B收下这批补给，做好准备——也许很快又需要你。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: War Supplies Cache
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41898, '提出这样的请求让我难受……黑根部族曾是我们的朋友和最亲近的盟友。尽管看着熟悉的面孔、认出昔日的朋友令人心痛，但知道他们已从盘踞心中的邪恶中解脱，还是让我欣慰。你为木喉争了光，朋友，为此你应当得到奖赏。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Denkeeper Sabatons Palefur Cloak Rotbark Sash
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41900, '看吧，这是我族人的造物——伟大的宁静灵契。它能以迅捷与优雅引导一个人的行动。木喉树液的精魂本身被注入了我们的力量，赋予了我们在这世上所拥有的恩赐。$B$B你为部族所做的努力，已为你赢得使用我们最传统灵契的权利。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Sapta of Tranquility
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41901, '看吧，这是我族人的造物——伟大的共心灵契。它能增强人对自然世界的抵御，以便寻求指引。木喉树液的精魂本身被注入了我们的力量，赋予了我们在这世上所拥有的恩赐。$B$B你为部族所做的努力，已为你赢得使用我们最传统灵契的权利。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Sapta of Communion
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41902, '看吧，这是我族人的造物——伟大的和谐灵契。它能强化并鼓舞自然本身的根须。木喉树液的精魂本身被注入了我们的力量，赋予了我们在这世上所拥有的恩赐。$B$B你为部族所做的努力，已为你赢得使用我们最传统灵契的权利。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Sapta of Harmony
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41903, '看吧，这是我族人的造物——伟大的亲缘灵契。它能让最破碎的灵魂重获生机，并提振士气。木喉树液的精魂本身被注入了我们的力量，赋予了我们在这世上所拥有的恩赐。$B$B你为部族所做的努力，已为你赢得使用我们最传统灵契的权利。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Sapta of Kinship
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41904, '看吧，这是我族人的造物——伟大的坚韧灵契。它能抵御深藏林中的腐化与剧毒。木喉树液的精魂本身被注入了我们的力量，赋予了我们在这世上所拥有的恩赐。$B$B你为部族所做的努力，已为你赢得使用我们最传统灵契的权利。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Sapta of Resilience
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41906, '$N！你来了！一看到他们回到小屋，我就知道你成功了，可我还是为你的安危担心。我由衷感谢你。你不仅为无辜者冒了性命，还闯过了寻常冒险者根本不会遇上的凶险。$B$B请从这些东西里挑一件，作为你今日善举的见证。$N！') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Healing Potion Lesser Mana Potion
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41907, '啊，是的，这些小玩意完好地躲过了火焰。外来者，我得谢谢你做的一切。没有你，它们肯定已经被毁了。我只能奉上微薄的报酬，但愿这点心意足够表达我的谢意。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Coastwalker Boots Riverflow Gloves
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41917, '布乌罗比也许被拦下了，但这场磨难远未结束。正如父亲所说，外面还有许多失落者已经迷失，而我们有责任把他们带回族群。这是件苦差事，我怕这不会是最后一个失去亲人的日子——但正因如此，我们必须竭尽所能阻止它发生。虽然我还经验不足、仍在受训，但我会尽可能支持父亲和长老们。$B$B我想了很久。虽然我在这里还有很多事要做，但你的作为在我心里点燃了一团前所未有过的火。这么多年来，我们把自己封闭在这片海岸，压抑自己，尽可能躲藏。可这并不是我想要的人生。但在确保村子安全之前，我不能离开。所以请收下这枚水晶。若你身陷险境，把它举向天空，我会在战斗中支援你。你可以信赖我，$N。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Jewel of the Morogai
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41933, '多可憎的造物。这进一步证明了我们这座圣殿中的生命正在一分一秒地腐烂。不过它仍有用途——它将为木喉铺平道路，去夺回被残暴恶徒撕走的一切。现在我能调配出足够强力的药膏，净化我们的神圣图腾了。$B$B$N，我们这小小集会向你致谢。凭你的勇气，我们朝净化木喉要塞迈出了第一步。收下这份精华，在你深入这魔物巢穴时使用。份量足够的话，你就能打破里面的结界，最终触及这一切的根源。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Essence of Purification
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41934, '在我们古老的教义里，有一则传说将所有熊怪部族联系在一起。它讲述了我族的诞生——据说在世界尚且年轻之时，双子神将我们带到了这个世上。那时他们还是幼崽，在卡利姆多未经触碰的荒野中嬉戏，在清晨沾满露水的草地上打滚。笑声弥漫在空气中，他们无拘无束的活力在四周飘荡。随着他们的力量满溢而出，湿草上的露珠落向巨树的根须，渗过树皮，与大地融为一体。日积月累，这些露珠逐渐生长，化作了那两位年轻熊神的模样。$B$B对我们熊怪来说，没有什么比协助始祖守护荒野更为重要。看着乌索尔第二次死去，让我的心充满痛苦与悲恸；像他这般高贵的存在，不该落得这样的下场。$N，木喉部族将永远欠你一份恩情。请收下这剂强效药膏，净化木喉要塞中残存的腐化。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Eternal Essence of Purification
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41939, '你说沃塔鲁斯？元素竟与凡人种族如此大规模地缔结盟约，令人担忧。尤其是在大地之环这里发生那些事之后。不过，这又引出了另一个问题：元素们究竟想从这样的联盟中得到什么？他们是黑风部族的仆从，还是反过来？若风之领主正把其他势力纳入麾下，那他们必定在为更大的图谋做准备。$B$B$N，谢谢你的勇气。你今日做到了了不起的事，也展现了作为我们教团萨满的潜力。其他人一定也期待你有更多出色表现。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Hammer of Earthfury Axe of Raging Winds Claw of Tempered Fire
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41942, '这些骨头里已无生命，可孢子仍在不断寻找养分，像扭动的寄生虫搜寻猎物。这不是自然现象，却也不纯粹是魔法。到这一步，它已是一种全新的力量混合体，要根除它绝不容易。$B$B我们想出的办法，概念上很简单：把这株树苗种进你带来的富化土壤，然后给树施加孢子，观察会发生什么。此前我们用被瘟疫侵蚀的土壤种树苗时，它们几分钟内就枯萎，只留下一具变异的空壳。我们推测，元素富化的土壤能保护树免受侵扰，让它自由生长。这需要些时间，若你再来，说不定运气好能亲眼看到。$B$B无论如何，我得谢谢你，也谢谢贝瓦利。每一步都让我们更接近彻底治愈这片土地。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Pendant of Reborn Vigor Rootbark Treads Ring of the Volcanic Hea
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41943, '元素已经告诉我你回来了，$N。水要重新变得清澈还需要时间。但既然再没有腐化被灌入玛拉顿，自然便能从容地自我修复。$B$B这是你为艾泽拉斯重归平衡所做的贡献，收下吧。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Spiritwater Orb Drape of Elusiveness Tempestrias Crown
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41944, '肉！还这么多！帕拉什卡，是谁让你张罗这些的？还是你自己要做的？不管怎样，对我来说都一样。有了这些补给，我们的守卫就有力气再抵挡那些异端好些天！你的作为该有回报。喏，一份德莱尼传统食谱，按这新世界的口味改过。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Recipe: Fried Strider with a Side of Berries
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41945, '嗯，我很意外。你听进去了，还带来了上等的脑子。看那脑浆滴在地上的样子……$B$B<费娜·玛达尔看着你手中的灰白之物，直咽口水。她动作飞快，一把从你手里夺过去，大嚼起来。汁液、血水和碎屑落在地上。>$B$B这种鲜美的滋味我怎么都吃不够——滑腻的表面，黏稠的质地！简直妙极了！你补上了你的过失，小家伙。至少对自己行为的后果，你还算负责。总之，别再在这儿惹乱子了！') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Elder Wand Trousers of the Unruly Youth Helm of Resonating Cryst
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41946, '好险。但愿这回能让他们长记性，不敢再来。你救了我的命和我这座宝贝农场，我感激不尽。你看，这片海岸的土壤性质特殊，作物很难生长；更何况即便待了这么久，你们世界的草木对我来说仍不易摸透。但我还是要为你的善举有所回报。拿去吧，都是自家种的！') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Moonwhisper Berry Moonwhisper Berry Bush
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41947, '那么那个恶棍终于伏诛了？太好了。上一次它发狂时，足足有二十三名族人死在它爪下。少了它，我们总算能睡得安稳些了。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Band of Sharpened Crystals Vengeance Gauntlets Treads of Traditi
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41965, '太妙了！最纯净的火焰——在这不起眼的火球之中，还跳动着一颗原初的心。世上任何邪恶，无论在此界还是他界，都躲不过它揭露一切的光。$B$B$N，时候到了。我们要将木喉要塞里的黑暗连根拔起。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Torch of Purifying Embers
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41966, '<纳科格脸上掠过一丝撕裂般的神情。起初你分辨不出，但从他身上传来的哀鸣与抽泣证实了你的猜测：他在哭。>$B$B历经这么多年的苦难与折磨，我的族人终于能松一口气了。笼罩我们大多数同胞、甚至我们一位神圣神灵的腐化，终于被平息。这一切都要归功于像你这样勇敢守护者的奋战。我的话无法真正表达我们对你与你的同胞的感激。你将永远是木喉的座上宾，是熊怪珍视的英雄。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Sacred Timbermaw Satchel
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41967, '<布罗兰风角长长地舒了一口气。>$B$B知道能睡个安稳觉，你替我免去了多少煎熬。今日你为风角一族立了大功，作为感激，我送你一件信物，外来者。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Brolans Grips Frontier Defender
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41968, '<布尔罗克云蹄不紧不慢地检视着那些角，好奇地用指节敲着骨面。>$B$B我想这正是我要找的东西，你干得好。$B$B<这个傲慢的牛头人嘴角扬起一丝笑。>$B$B来，收下这个，就当是云蹄部族的一点谢意。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Cloudhoof Claymore Forefather Mantle Bulroks Leggings
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41969, '多么奇妙的材料，如此鲜亮，如此多彩！接下来的仪式会因它大放异彩，肯定比上一件法衣好得多。$B$B谢谢你，$C，请收下这份奖励。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Darkhide Bracers Windplate Belt
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41974, '<戈德纳克不紧不慢地端详着那片鳞，看它在光下熠熠生辉、散发魔力。>$B$B看来我要找的就是这东西。你干得好，来，收下这些金币，还有我给你的奖赏。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Gordnaks Respite Ragetotem Rifle
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41977, '我整个少年时代都被这样的遗物环绕。风角的工艺确实精湛。$B$B没有你的帮助，这段历史就会被时间吞没。谢谢你，为今日你所做的一切。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Saghs Pendant
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41978, '血债血偿。你做得很好，用复仇回敬了这份邪恶。但愿你能体会我此刻的满足——即便怒火仍在我心中燃烧，我已得昭雪。$B$B谢谢你成为我怒火的执行者。请收下这些金币，是我，也是那些逝去之人的敬意。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Hauberk of Bloodshed Cloudtotem Cloak
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41982, '<凯恩以赞许的目光看着你。>$B$B你做得很好，为牛头人带来了安宁。死亡图腾再也不能作祟了，年轻的血液。请收下这件东西，愿它在你往后的日子里为你带来好运。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Bloodhoof Sash Stormhoof Shackles Stonemane Boots
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41986, '这些真了不起。你确实有一手好厨艺——照这水平看，迪尔格可得当心，别太早被你抢了位置。总之，这是做好的锅具。带给迪尔格，告诉他随时可以回来，前提是他地精的自尊心答应。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Finished Cooker Prototype
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41989, '你拿到了！不过……它似乎已经受损。真可惜，但也许这样最好。这样一来，那些妄图在这世上散播纷争的人，就没法拿它作恶了。我会带着它回到大地之环，此刻它在我手上是安全的。再次谢谢你，$N。没有你的帮助，纳迦也许已经把它据为己有了。请收下这个，作为大地之环的赠礼。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Mace of Natural Communion Stonewrought Grips
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41990, '办妥了吗？太好了，那我们别再在这儿浪费时间了。我去收好圣物，然后到莫罗盖村跟理查德会合。再次谢谢你帮忙，陌生人。我很感激。来，你可以自己留一件宝物，就当是我的谢意。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Tablet of Marasethil Glaive of the Royal Guard
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41991, '<克拉尔特吐出一口长气，如释重负，脸上的苍老愁容也松缓下来。>$B$B外来者，你替我卸下了重担，为此我得谢你。我的储备正为即将到来的冬眠一点点攒起来。$B$B请收下这个——让它证明，并非所有熊怪都沉溺于狂怒。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Kralts Forage Belt Bracers of Hibernation
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41993, '骄傲与憎恨蒙蔽了他们，使他们走上狡黠而诡秘的道路。他们选择拥抱年轻的洛修的阴暗面——当整个世界都与你为敌时，那个忤逆的兄弟确实颇具吸引力。$B$B潮流正在转变。暖意让我的毛发微微发颤。安舍又与我们同在了。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Sharpshooters Lucky Bullet Robes of the Bonerattler Brutesguard 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41994, '那就这样吧。今天是沉重的一天，但已无所谓。黎明到来时，安舍的温暖会拥抱我。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Wilted Moonflower
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41996, '这么说你确实削减了它们的数量。嗯，聊胜于无。真到了忍无可忍的时候，我就往耳朵里塞点丝绸。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Aquadynamic Fish Attractor
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41999, '虽然眼下还没法给你做新衣服，但你可以在这些里挑一件——都是用我手上最后一批材料赶制的。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Mothsilk Guard Mothsilk Cape
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (42000, '我感觉到南方传来了一丝安宁，你的任务确实成功了。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Star of Marasethil
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (42007, '以造物主之名，他说对了。哦，奥杜姆，你这个疯子！拿命去赌这东西根本不值得！$B$B<布罗哈恩长长地吐出一口气，疲惫不堪。>$B$B$N，我这位朋友一直在寻找一件他认为是泰坦遗物的古物——泰坦，那些曾造访艾泽拉斯的天界存在。我们伟大的铁炉堡里，许多学者与教授都推测矮人的诞生与那些神祇之间有关联。他以为你手上这件东西能让矮人更接近真相，可惜它似乎并不完整。匀矛是用性命换来这惊人发现的，我会带着骄傲与敬意对待他的牺牲。等我在暴风城的事了结，我会把它呈交给大图书馆的资深探险家麦格拉斯做进一步研究。$B$B至于你，无论出于你的英勇还是对考古的贡献，都该有一份公正的奖赏。旅人，愿你一路顺遂。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Archaeologists Lantern
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (42008, '传闻一点不假，我很少见到如此柔滑细密的皮毛。我已经等不及要动手处理它了。按约定，也有你一份奖励。我相信你会派上大用场。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Thalassian Silk Cape
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (42012, '你的朋友胆子不小，也许还有点迟钝。不过礼物就是礼物，下次他再来，我照样欢迎。你从小龙身上取下的那块水晶叫星辰碎片，是陨石的碎屑。瞧，谜团解开了。那么，除非你还有德莱尼水晶要给我，我就回去忙我的事了。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Draenic Opal Band
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (42014, '很好，洛修的影响正在消退，干得漂亮。就当是允许风角一族在我的村子外多待一阵子了。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Moonsbane Dirk of the Blue Moon
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (42015, '自然自有其规律，她的身体会像所有躯体一样归于尘土。我祈求洛修保全她的心智，让她在她曾深爱的群星间漫游。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Moonlit Tunic Greaves of the Moon
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (42018, '阿什托泰姆送来一份滑稽的礼物。他本是要去与月蹄一族商谈邦交与盟约的，却被挡在门外，于是决定把月蹄长老最老的朋友的心脏当作礼物送我——那个人如今已被他自己视作敌人。真是乱象丛生。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Grimtotem Feathers Helm
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (42019, '你居然真找到了一头。很好。交给我，然后等着。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Stonetotems Cleaver Stonetotems Knuckle Duster
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (42021, '成了。它虽不如原版那般强大，但这份精华足以浇熄那些在圣洞里散布枯颚腐化的火盆。若还需要更多，你知道上哪儿找我，勇敢的冒险者。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Essence of Purification
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (42036, '你依言将锁扣嵌入凹槽，它伴着一声沉重的咔哒声弹入装置。你插入钥匙不久，箱盖便打开了——收下你应得的奖赏吧。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Perfumed Envelope Ephanel, Dawn of Ruination Lophanel, Dusk of Calamity
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (42037, '哈哈！你办成了，你救了我的小命！$B$B这事要是传出去，我肯定得回去当巡山人了。你帮了我一个大忙，这份回报你受之无愧。$B$B哦，还有——这事别跟任何人提。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Pilots Knife Spare Mountain Boots
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (42039, '这么说，乌布卡兹被干掉了？$B$B<格拉尼泰比尔德顿了顿，嘴角浮现一丝笑意。>$B$B我简直不敢相信。我毫不怀疑还会有别的巨魔站出来当酋长，但接下来的这些天里，丹莫洛可以太平一阵了。$B$B趁他们内斗未了，咱们有时间好好庆贺一番！') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Heavy Chain Bracers Sash of Illumination Deep-Thread Shawl
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (42041, '别磨蹭了！没时间可浪费，小家伙。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- The following spell will be cast on you: Survival
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (42042, '走到这一步让我痛心，但他们的执迷已经离救赎太远。为了自然与其间的生灵，他们只能回归循环。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Bloom of the Sun Keepers Boots Crown of Bandalar Dryadroot Neckl
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (42051, '干得好。在水、大地之环和你的协助下，元素们归于平静——它们明白自己的怒火尚不必宣泄。月语海岸的凡人将以坚定的信念面对此地的动荡。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Helm of the Earthen Circle Bands of Water Earthen Circle Sandals
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (42053, '挑吧。一件归我，另一件归你。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Jaw of Starcaller Jaw of Spellstriker
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (42057, '是时候领悟安舍的教诲了——大地母亲的右眼。愿他的光辉照亮你的前路，也灼瞎那些妄想伤害大地母亲宠儿之人的眼睛。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- The following spell will be cast on you: Light of Anshe
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (42059, '洛修常被误解，但他和大地母亲的双眸一样，都是她的一部分。闭上眼睛，听听我们族人的传说吧。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- The following spell will be cast on you: Spiritwalk
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (42064, '很好。这能让我们多撑一阵子。$B$B别以为事情就此了结。那次偷窃并非迫于绝望——那是试探。他们想看看我们会如何反应，看看我们是否软弱。$B$B现在他们知道了。$B$B他们还会再来试探，他们总是如此。受伤的野兽被逼到墙角时反而更胆大。若我们按兵不动，他们就会聚拢，然后在暗处扑上来。$B$B下一次，我们不会再追回被夺走的东西。$B$B下一次，我们要烧掉那只伸向我们的手。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Blackroot Wraps Shield of Alahthalas
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (42069, '这是什么？$B$B<阿恩达尼尔凝视着你取回的器物。他的目光停留得太久，仿佛那东西也在回望他。>$B$B就是这个？$B$B是的……当然是。现在我看清了。$B$B魔力已耗尽、被抽干，但毫无疑问。这就是源头。这就是他们找到的东西。即便已经空了，它仍因某种目的而低鸣。$B$B<他小心地举起它，近乎虔诚地在光中转了一圈。>$B$B如此精准。没有一处赘余，没有为虚荣添的纹饰。这不是精灵的工艺。$B$B我研究过我们过往各个角落的遗物：上层精灵的宝库、大分裂前的废墟——没有任何一件能与之相比。制造它的东西，思维方式与我们不同，感受方式也与我们不同。而曾流经它的力量，足以在片刻间把训练有素的奥术师抽成游荡的空壳。$B$B可我还是甩不掉一个念头：这只是一个外壳。一把钥匙，也许。是注定要再次被使用的东西。$B$B我必须立刻回阿拉萨拉斯。哦，表弟……这一次，我没有辜负你。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Sunsworn Glaive Robes of Nox
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (42077, '那么这就结束了。大德鲁伊蛾幕死了，伊瑞丝·月舞者还活着。他本想将月亮从天上击落——若不是你出手阻止，他几乎做到了。我们必须把这件事报告给我父亲，不过在去之前，你这一路的英勇作为理应得到奖赏。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Lens of Marasethil Turquoise Signet of Losho Crown of Anshe
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (42085, '我们的祖先降下了不小的征兆，可我还不知道该如何解读……不管怎样，又一届庆典落幕了。若没有你帮忙，我恐怕还在等月蹄村的援手。$B$B外来者，我得为你的慷慨有所回报。请收下这个，代表我自己，也代表我部族中的所有人。愿你旅途平顺，前路无虞。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Moonhoof Ceremonial Pendant Starstrider Band Dragon Dust Residue
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (42087, '这么说……它真的一直留在那里。$B$B<塔拉尼斯沉默地端详着这件器物良久。>$B$B了不起。单凭工艺，它就能追溯到辛艾萨莉建城之前数百年。而那月光的共鸣……是的，即便此刻我也能感觉到。这绝非单纯的礼仪用器。它被使用过、被研究过、被尊崇过。艾露娜瑞斯的祭司们一定曾在它的光下修行，学习借它引导艾露恩的祝福。$B$B你今天带回的不只是一件遗物，而是我们过去的一角——否则它或许已随那座神殿一同湮灭。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Elunarian Necklace
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (42088, '那就这样结束了。$B$B我并无快意。只是……若放任不管，死的人会更多。我们会继续盯着他们其余的部族——若这腐化继续蔓延，我们就会知道。在那之前，纳尔瓦利斯角是安全的。这才是要紧的事。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Boots of Krethis
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (42090, '塞彭提亚女士……还有塔贾克斯。$B$B<银痕头一次允许自己露出一个心满意足的点头。>$B$B很好。非常好。$B$B没了他们，潮刃会分裂成互相敌对的几支。纳迦在缺少强势领袖时，素来谈不上团结。这给了我们优势。奈迪斯废墟或许终于能重归安宁了。$B$B这件事该让高阶祭司知道。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Moonlit Hauberk Moonstride Leggings
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (42091, '塞彭提亚女士和塔贾克斯都死了？$B$B在对抗伊利丹的战争里，这两个名字常被提起。他们的战团在这片海岸留下的伤疤至今未愈。若他们真的倒下，那个时代最后的阴影之一便终于散去了。$B$B奈迪斯沉寂得太久了。纳迦被赶走后，废墟或许终于能重归。不会很快——这样的创伤需要时间愈合。但随着时间……我的人民会回来。家园会重建，神殿会修复，森林将再次听到我们的声音。$B$B月语海岸曾是卡多雷在艾露恩之光下安居乐业之地。也许，慢慢地，它会再度如此。$B$B$C，你帮助这个未来成为可能。纳尔瓦利斯角的哨兵们感激你……我也一样。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Hope of Nendis
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (42092, '召星者死了？$B$B很好。最紧迫的障碍就此清除。$B$B蓝龙军团很少如此凶悍地守卫某样东西——除非它蕴藏着极大的奥术意义。$B$B一颗浸透奥术能量的陨石……还有巨龙像秃鹫般在它周围盘旋。$B$B没错。这个陨坑里绝不止一颗坠自天上的石头那么简单。那条龙死了，其余的可能也会收敛些胆量。又或者，它们会好奇到把真正守护的东西亮出来。$B$B无论如何，你给了我们查明真相的机会。$B$B而我非常想抓住它。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Dragonbane
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (42094, '这么说，林地安静下来了……暂时而已。$B$B我本希望腐化没有蔓延到这一步，但迹象再清楚不过。这些德鲁伊已不再侍奉荒野的平衡。有什么东西引导他们走上了这条路。$B$B泰兰达斯岛的日之林地也许有答案——我的一位盟友在那照看林地。$B$B去找米拉鲁恩姊妹吧。她比大多数人更仔细地守望着森林。把你看到的都告诉她。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You will receive: Starglass Monocle
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (9333, '干得不错，$N。挑一副护手吧，聊表谢意。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Gloves of Undead Cleansing Handwraps of Undead Slaying Handguard
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41275, '嚯，是梅瓦派你来的？那丫头好久没在这儿露过面了！她要我教你金饰加工？这倒怪不得她——毕竟我确实是全艾泽拉斯最出色的珠宝匠。$B$B那就别再等了，如何？') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Oho, so Mayva sent you? That snappy gal hasnt shown her face around here in AGES! And she wants me t
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41276, '一路远行而来吧？这片土地算不上好客，却有一种原始的、未经触碰的美，别处难得一见。不过你并不是为此而来，对吧？说吧，是谁让你来找老加卡尔的？$B$B金饰加工？这是我许久不怎么施展的老手艺了。部落更用得上我的炼金本事。但若你愿意拜我为师、听我讲讲能讲的东西，那就请便吧。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Long travel, I take it? These lands arent the most welcoming, but they offer a primal beauty, untouc
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41278, '<瑟格伦的目光在你和你带来的水晶之间来回移动。盯着你看了好一会儿后，他点了点头。>') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- <Thegrens gaze switches between you and the crystal you brought with you. After staring at you for a
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41280, '<与矮人无可挑剔的切工相比，你对自己那些拙劣的仿作几乎感到羞愧。可是出乎意料的是，瑟格伦脸上又浮起一丝笑意，一股成就感令你精神一振。$B$B下一步在等着你。>') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- <Comparing them to the dwarfs flawless cuts, you feel almost embarrassed looking at feeble attempts 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41281, '<把沉重的石板呈给瑟格伦时，你感到一阵自豪——他琥珀色的眼睛因兴奋而发亮。石板的晶光在荒芜之地刺眼的烈日下反射得格外美丽，让你所有的辛劳更显值得。$B$B瑟格伦转向你，赞许地点了点头。最后一步就在眼前。>') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- <Presenting the heavy slab of stone to Thegren brings a sensation of pride to you, as you see his am
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41290, '<那位上层精灵不屑地打量你。>$B$B先是下头那个笨手笨脚的人类，现在又轮到你？一位艺术家这辈子就不能有一次清静吗？说吧，是谁让你来找巧匠的？') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- <The Highborne eyes you dismissively.>$B$BFirst this bumbling human down there, and now you? Can an 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41296, '你臭得很，$R，臭气冲天。我能闻到你身上那股天真的、无谓的希望的可鄙气味。让我猜猜——是桑夫·克拉和他那帮可怜虫派你来从我伟大的头脑里套取知识吧。若真是如此，那我倒迫不及待想看你脸上失望的表情了。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You reek, $R, horribly. I can smell the despicable stench of naivety and senseless hope on you. Let 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41297, '果然还是损坏了。粗野蛮徒。至少里面的东西完好无损。那你就算走运了。不过，这卷轴……难道是……？肮脏的东西，你的贪婪帮了我大忙，但你的报应还不到时候。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Damaged, as to be expected. Savage brute. Atleast its contents are intact. You can consider yourself
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41298, '<那破碎者德莱尼以出人意料的力量抓住那颗断下的头颅。他朝马托加血淋淋的面皮上啐了一口，把它摔在地上，又狠狠踩进红色的沙土里。>$B$B可悲的东西，毁灭与荒芜的使者。愿你祖先将你的灵魂撕成碎片，因为你背叛了你的族人、你的血亲！你夺走了我们——夺走了我逃离的手段——这让我从心底感到恶心。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- <The broken draenei grabs the decapitated head with unexpected force. Spitting on the bloodied skin 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41300, '派个手下独自去解决自己的麻烦？没想到那个扭来扭去的小侏儒还有这一手。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Sending a goon on his own to sort out his problems? Now this is something I hadnt anticipated of tha
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41304, '<塔克纳兹读着你在那地精身上找到的契约。他越往下读，绿色的皮肤就越发涨红。>$B$B啊，那些背后捅刀、啃伤口过活的穴居人！离开风险投资公司是纳特这辈子做过最正确的事，我受够了他们那些见不得光的手段。我不仅丢了所有珍贵的珠宝，还失去了最好的承包商，要找个替代的人不知要等到何年何月！哦，格里兹比，你这老混蛋，你本该有更好的下场，好得多……') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- <Tacknazz reads the contract you found on the goblin. The further he reads, the redder his green ski
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41307, '这是什么？特拉西斯的货？我等这个等了好久！那地精和他那一塌糊涂的服务到底在搞什么？不管怎样，谢谢你替他完成了活。要不是他有那么独家的货源，这就是我最后一次在他那儿订货了。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- What is this? Traxis delivery? Ive been waiting ages for this! Whats up with that goblin and his lac
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41308, '我可不敢称那个小东西为伙伴，但我们之间共享着许多宝贵的知识，所以我才容忍她的存在和请求。说吧，她今天又要什么？') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- I dare not call that tiny being a partner, but we share much valuable knowledge between us, so I tol
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41310, '卡德加？这名字我已许久未闻，自他离开这个世界后，我以为再也不会听到。无论他在何处、是生是死——但愿他的灵魂自由而清明。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Khadgar? A name I havent heard in ages and one I thought Id never hear again following his departure
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41311, '那件握物又回到了我手里，简直像个诅咒。你居然毫发无伤地回来了，令我十分佩服——你的实力已可与大英雄比肩。$B$B现在说说那件握物……') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- The clutch has found its way back to me, almost like a curse. I am most impressed you returned somew
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41313, '这些看上去极不自然。地脉水晶只在罕见的情况下，当地脉精华渗过地表时才会自行凝结，可这些……它们的形成方式似乎不同，某种意义上像是被强行促成的。嗯，蹊跷……$B$B<大法师克希雷姆一边端详着水晶，一边沉思片刻。突然，他灵光一现。>$B$B$N，对此有许多说得通的解释。但要证实我自己的推论，我得先做些试验。你愿意帮我吗？') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Those appear positively unnatural. Ley line crystals materialize themselves on rare occasions when f
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41314, '令人遗憾，也令人不安。今后挑选学徒，我必须更加审慎。塔蕾莎竟如此鲁莽，实在令人费解，我没想到她会做出这种举动。诚然，她的急切显而易见，但我原以为——也希望——那是出于对知识的追求，而非对力量的贪求。无论她为谁效力，我都会让他们为自己的所作所为受到清算。$B$B不过，聚焦宝珠已回到我手中，我们终于能查清这地脉之谜了。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Regrettable, and concerning. I have to be even more selective in my choice of apprentices in the fut
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41317, '哎哟，这玩意儿真烫！弄到手一定费了不少劲，幸好你比它更硬气，是吧？那么，别再等了，把这宝贝撬开！$B$B<凡兹把碎片移到沉重的锁上，碎片散出灼热的气息，锁应声开裂，随即落进沙中。凡兹兴致勃勃地翻起那本书。>$B$B空的。空的。空的。空的！除了两页之外全是空的！我简直不敢信！这是什么恶劣的玩笑吗？！') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Ouch, that thing is hot! Mustve been real tough to get, luckily youre on the tougher side of life, e
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41320, '如你所见，我所目睹的一切，为避难所中的同胞描绘出一幅惨淡的图景。我带领他们来到这个世界寻求安宁，如今我们的过去却再度作祟。我必须阻止这一切，可凭我一人无能为力。陌生的朋友，你愿意像帮助桑夫·克拉那样帮我一把吗？') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- As you can see, what I have witnessed paints a grim picture for my brethren at the Harborage. I have
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41321, '<阿克扎多尔接过黏滑带血的大脑，一块块嚼了下去。看上去令人作呕。>$B$B唔，口感有点像海绵，倒不难吃。相信我，我吃过更糟的。谢谢你，$N，我已经能感觉到神智的虚弱在消退了。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- <Akh Zador takes the slimy, bloody brains and chomps them piece by piece. It is revolting to look at
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41322, '辛香带辣——这正是德莱尼菜肴的典型风味。谢谢你带来足够的食物，让我恢复了元气。你的善意弥足珍贵，我真希望能用我族人的传统菜肴回报你，一道用德拉诺食材烹制的菜。不过我扯远了，在这儿，多愁善感毫无用处。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Zesty and spicy - a combination typical for draenei cuisine. Thank you for providing me with enough 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41323, '我的手杖！上一次见它这般残破，还是多年前我们逃离德拉诺的时候。永远感谢你，$N。还有这个……你们叫它魔精？这股盘旋的能量对我来说完全陌生。你们这个世界恐怕永远都会让我困惑。$B$B<阿克扎多尔以拳捶胸，向你的事迹致敬。>') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- My cane! Ive only seen it this disheveled after we escaped Draenor years ago. Eternal gratitude to y
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41324, '是阿克扎多尔大人派你来的？！真是太好了！我和部族的人都担心得要命，甚至已经做了最坏的打算。失去这样一位挚友、可信的首领和精湛的裂隙行者，我们谁也承受不起。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Master Akh Zador sends you?! What a relief! Me and the tribe were worried sick, and had already fear
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41325, '一个幽影？它还提到桑夫部族和阿克扎多尔被奴役？！这消息太糟了，$R。为了我们所有人，但愿我错了——但我担心避难所正面临危险，极大的危险！') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- A shadowed specter? And it spoke of the enslavement of the Sanv tribe and Akh Zador?! This is grim n
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41326, '我悲痛欲绝。即便在最荒诞的梦里，我也想不到会如此。桑夫·塔斯达尔，曾是我们的酋长、我的导师，也是我族高贵的领袖，竟屈从于燃烧军团的甜言蜜语。若不是你和阿克资阿多，我和族人便会随他回到德拉诺，余生都做军团阴谋的傀儡。$B$B避难所永远欠你一份人情。言语无法表达我对你这份无私的感激有多沉重。所以，请收下这份心意——它来自这座小小圣所里所有德莱尼人。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Garbs of the Riftwalker Nethershard Band Harborage Defender Paul
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41338, '听到月光林地愿伸出援手，令人安心，年轻人。我们正面临的动荡应是我们所有人的事，置之不理难道不危险吗。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Moonglade sending support is assuring to hear, young one. The turmoil we are facing should be the co
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41339, '你说一个幽魂？还是白雄鹿的模样？若你亲眼所见属实，我们就不能再拖延了！') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- A spectre, you say? In the form of a white stag? If what your eyes witnessed is true, then we cannot
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41340, '干得好，$C。见你如此迅速地完成任务，让我对接下来要托付你的事不再存疑。你或许不知，我的同胞与我皆是玛洛恩的后裔。正是他与月神伊露恩的结合，孕育了我们的父——塞纳留斯，而他又创造了我们。这事不仅关乎海加尔山或我族的安全，也关乎整个艾泽拉斯。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Well done, $C. Seeing you complete this task so quickly reassures me to not be doubtful of what I wi
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41341, '看到这些强大的饰品，会让你这样的凡人想起世间存在的种种力量。它们或许超出常人的理解，但也不要低估你自己在其中的作用。凡人一次又一次地证明，他们是改变艾泽拉斯命运的关键。你所做的每一件事都会带来后果，或早或晚。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Setting eyes upon these powerful trinkets reminds mortals like you of the forces present in this wor
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41347, '<这个瞎眼醉汉明显已经醉了。唯有打嗝和嗳气证明他还陪着你。他看上去已濒临死亡。>$B$B你想要啥？！没看见俺正忙着呢吗？！') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- <The blind drunkard is visibly intoxicated. Hiccups and burps are the only signs showing he is still
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41349, '<在泥土里翻找了片刻之后，你发现一具骸骨。从獠牙判断，那是兽人的遗骸。两样东西引起了你的注意：一条项链，外观与戈拉克在日志中描述的一模一样——这一定是他妻子梅拉尔。可惜，它不是蒂莉亚的项链。另一样是一把残破的剑，剑身已断，是年久还是战损，无从判断。>') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- <After a few minutes of hard work rummaging through the dirt, you come across a skeleton. Judging fr
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41350, '这把剑深深烙在我的意识里，就算想忘也忘不掉。若你有时间，就让我讲讲我最出色的弟子的事吧。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- This sword is etched deep into my consciousness, something I cannot forget even if desired. Should y
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41356, '你又一次完成了任务。不论你还剩下哪些亲人，我希望他们想到你时会感到自豪。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You once more succeed to fulfill your task. For whatever kin you have left, I do hope they feel prid
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41357, '如同每一位伟大的奥术操控者，玛里苟斯渴求知识与试验。他将自己的法力注入诺森德的寒冰——或许那最接近某种元素的「原生」诞生地。也就是说，他那愚蠢的实验并没有好结果。如你所见，它并不像元素生物，而是一种冷酷无情的杀戮手段。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- As every great wielder of the Arcane, Malygos has the thirst of knowledge and experiment. He infused
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41359, '我……我恐怕得在某种程度上同意她的话。但怀着如此仇恨，还鼓吹灭绝整个种族？我的心沉了下去。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- I- I am afraid I have to agree with her words to a degree. But to harbor such hatred and encourage g
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41361, '山中之血！自从索瑞森的党羽控制了黑石山内外的所有采矿作业，想弄到这么一件宝贝就难上加难。而这一份似乎还是特别的品种……') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Blood of the Mountain! Getting your hands on one of those beauties has been really difficult, ever s
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41365, '虽说生者如今被视为威胁，他的死也毫无道理可言。但这事必须有人去做……$B我会用余生哀悼你，威廉。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- While the living are now seen as a threat, his death was unjustifiable. It needed to be done...$BI w
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41370, '看到守护者的精华，我都在发抖——你能把它带到这里，足以证明你的意志之坚与体魄之强。如今所有部件都已齐备，修复权杖只需片刻。请退后一步，过程中恐怕会迸发不稳定的能量与狂暴的魔力。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- I am trembling at the sight of the guardians essence, that you were able to carry it here is a testa
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41371, '我从未见过这样的宝石。那青绿的色泽、它的结构与表面，在艾泽拉斯无可比拟。你为追寻真相所付出的努力，又一次令我惊叹。现在，让我们把这件事了结吧。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Ive never seen anything like this gemstone before. The teal color, its structure and surface are inc
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41377, '这么说，传说中的月神镰刀被找到了。梦风派你来找我算是明智，尽管他治愈海加尔的努力走错了方向。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- So, the fabled Scythe of Elune has been found. Dreamwind has been wise to send you to me, even if hi
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41382, '纯净的狼人之血，正如乌尔所描述。是的，这非常有用。它们曾是伊露恩最宠爱的孩子，能得到它们未被腐化的血……这将是仪式中的关键……不过现在听我说，我有很多事要讲。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Pure worgen blood, just like Ur described. Yes, this will be very useful. They were once the favouri
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41385, '狼人神父……一个浸透阴影的名字，却可能握有我们获救的钥匙。你挖出的这本日志虽然晦涩，却可能是揭开他那邪恶存在的真相的引线。让我们再次钻研乌尔的教诲，其中藏着破解这个谜团的智慧。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Father Lycan... A name steeped in shadows, yet one that may hold the key to our salvation. This jour
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41387, '铁藤之根是一种凶悍的植物。被拔起时，它会缠住捕获者，试图将其拖倒在地，最终把人耗尽。而你并没有向这股自然之力低头。你心念清明，意志如铁。上一个通过这项考验的人是我的学徒萨克戈斯，那是许多年前的事了。或许我在你身上发现了非凡之人。接下来的试炼会证明我的判断是否正确。$B$B<马赛厄斯抽出匕首，快手一挥——快得你几乎看不清——把缠在你身上的藤蔓割了下来。>$B$B这东西不该浪费，用这藤根能泡出上好的茶。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- The Ironvine Root is an aggressive plant. When uprooted it clings around its captor, trying to drag 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41391, '贾里德·沃斯？这名字让我想起好些事，真不愿如此。若这份文件属实，我们得立刻动身。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- Jared Voss? I hate that this name rings several bells. If what is in this document is true, then we 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41639, '<女巫以一种令人不适的方式咯咯笑着。>$B$B到底还是派上了用场。喏，我自酿的几瓶药水，专门给你的。你可以在这儿待一会儿，想问什么就问。这片林子知道的事，多数人是不敢问的……') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Elixir of Detect Lesser Invisibility Lesser Invisibility Potion 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41916, '我感觉你周身带着一股肃穆之气。办妥了吗？我这桩过错终于被纠正了吗？$C，你为我族人立下了大功。你不仅把我们从不祥的结局中救了出来，还让我们看清：我们沿袭了数百年的路，莫罗盖人不应再走下去了。某种意义上，布乌罗比是对的——德莱尼人必须改变，才能为族人确保一个新的未来：一个不再充满恐惧、而是充满坚韧的未来。只可惜他曲解了自己信仰的本意。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Belt of Unclouded Guidance Brutalist Shroud Defenders Cudgel Cho
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41953, '那个长角的恶徒；你说这萨特叫塞勒娜？他吸收了晶簇的能量，注满自身，与德莱尼水晶融为了一体？！即便在这新世界，也还能见到这等亵渎之事。$C，德莱尼水晶的力量极具诱惑，一旦触及它脉动的能量，就需要极大的意志力才能不被吞没。有……些故事说，德莱尼人沉溺于水晶成瘾，最终自身晶化，自己也变成了德莱尼水晶。于是他们回到德拉诺，汇入它生命之血的循环。$B$B眼下我得为你带回的晶簇碎片准备净化仪式。这需要时间与心力，但我和莫罗盖人一样欠你太多。你对我族存续的持续支持，必将得到回报。请从这些手镯里挑一只，愿它能护你抵御将来临的邪恶。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Bracelet of the Defender Bracelet of the Visionary Bracelet of t
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (42023, '拿好了，朋友。你能感觉到其中奔涌的灵力吗？未经磨练的人会在它的威势下发抖。所以请务必善用它，去对付黑暗的敌人。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- You can choose one of these awards: Guile of the Stag Guile of the Ursa Guile of the Hippogryph Guil
